bool Backend::DrawSortFilterLegend(plume::RenderTexture* back,plume::RenderFramebuffer* framebuffer,
                         plume::RenderFormat target_format,const plume::RenderRect& guest_fit) {
  constexpr unsigned width=av2::legend_art::width,height=av2::legend_art::height,pitch=width*4;
  if(!sort_filter_legend_attempted_) {
    sort_filter_legend_attempted_=true;
    av2::legend_art::Asset asset;
    if(!asset.load(av2::sort_filter_legend::runtime_path)){REXGPU_ERROR("[gpu] sort/filter legend asset missing or invalid");return false;}
    sort_filter_legend_texture_.desc.width=width;sort_filter_legend_texture_.desc.height=height;
    sort_filter_legend_texture_.desc.kind=ResourceKind::kSampledTexture;sort_filter_legend_texture_.desc.format=HostFormat::kRGBA8;
    sort_filter_legend_texture_.width=width;sort_filter_legend_texture_.height=height;
    sort_filter_legend_texture_.format=plume::RenderFormat::R8G8B8A8_UNORM;
    sort_filter_legend_texture_.texture=device_->createTexture(plume::RenderTextureDesc::Texture2D(width,height,1,sort_filter_legend_texture_.format));
    sort_filter_legend_upload_=device_->createBuffer(plume::RenderBufferDesc::UploadBuffer(uint64_t(pitch)*height,plume::RenderBufferFlag::CONSTANT));
    if(!sort_filter_legend_texture_.texture||!sort_filter_legend_upload_)return false;
    auto*mapped=static_cast<uint8_t*>(sort_filter_legend_upload_->map());if(!mapped)return false;
    const bool decoded=asset.fill(mapped,pitch);sort_filter_legend_upload_->unmap();if(!decoded)return false;
    if(!SampleSet(sort_filter_legend_texture_)||!BlitPipeline(target_format,true))return false;
    Transition(sort_filter_legend_texture_,plume::RenderTextureLayout::COPY_DEST);FlushTransitions();
    lists_[slot_]->copyTextureRegion(plume::RenderTextureCopyLocation::Subresource(sort_filter_legend_texture_.texture.get(),0,0),
      plume::RenderTextureCopyLocation::PlacedFootprint(sort_filter_legend_upload_.get(),sort_filter_legend_texture_.format,width,height,1,pitch/4,0));
    sort_filter_legend_ready_=true; // Immutable texture/upload retained until existing guarded Destroy.
  }
  if(!sort_filter_legend_ready_)return false;
  const int gw=guest_fit.right-guest_fit.left,gh=guest_fit.bottom-guest_fit.top;
  if(gw<=0||gh<=0)return false;
  const auto rect=av2::sort_filter_legend::fit(guest_fit.left,guest_fit.top,gw,gh);
  if(!rect.valid)return false;
  const plume::RenderRect fit(rect.left,rect.top,rect.right,rect.bottom);
  Blit(sort_filter_legend_texture_,plume::RenderRect(0,0,int(width),int(height)),back,framebuffer,target_format,fit,1.0f,true,true);
  return true;
}
